package net.nuggetmc.tplus.compat.bukkit.event.block;
import net.nuggetmc.tplus.compat.bukkit.event.*; import net.nuggetmc.tplus.compat.bukkit.block.*; import net.nuggetmc.tplus.compat.bukkit.entity.Player; import net.nuggetmc.tplus.compat.bukkit.inventory.*;
public class BlockPlaceEvent extends Event implements Cancellable { private final Block block; private final BlockState replaced; private final Block against; private final ItemStack item; private final Player player; private final EquipmentSlot hand; private boolean cancelled,canBuild; public BlockPlaceEvent(Block block,BlockState replaced,Block against,ItemStack item,Player player,boolean canBuild,EquipmentSlot hand){this.block=block;this.replaced=replaced;this.against=against;this.item=item;this.player=player;this.canBuild=canBuild;this.hand=hand;} public Block getBlock(){return block;} public BlockState getBlockReplacedState(){return replaced;} public Block getBlockAgainst(){return against;} public ItemStack getItemInHand(){return item;} public Player getPlayer(){return player;} public boolean canBuild(){return canBuild;} public void setBuild(boolean v){canBuild=v;} public EquipmentSlot getHand(){return hand;} public boolean isCancelled(){return cancelled;} public void setCancelled(boolean v){cancelled=v;} }
